{"code":"import random

def generate(rng):
    H, W = 9, 13
    g = [[0]*W for _ in range(H)]
    # Fixed-size compact 8 marker, with varied location.
    r8 = rng.randint(1, H-3); c8 = rng.randint(1, W-3)
    for r in (r8, r8+1):
        for c in (c8, c8+1):
            g[r][c] = 8
    # Make a connected, irregular 2-object on one side of the marker,
    # leaving at least one-cell separation and room to translate toward it.
    side = rng.choice(['left','right','above','below'])
    cells = set()
    if side == 'left':
        base_r, base_c = r8, max(0,c8-rng.randint(3,5))
        for i in range(rng.randint(4,8)):
            cells.add((base_r+rng.randint(-2,2), base_c+rng.randint(0,2)))
    elif side == 'right':
        base_r, base_c = r8, min(W-3,c8+rng.randint(3,5))
        for i in range(rng.randint(4,8)):
            cells.add((base_r+rng.randint(-2,2), base_c+rng.randint(0,2)))
    elif side == 'above':
        base_r, base_c = max(0,r8-rng.randint(3,5)), c8
        for i in range(rng.randint(4,8)):
            cells.add((base_r+rng.randint(0,2), base_c+rng.randint(-2,2)))
    else:
        base_r, base_c = min(H-3,r8+rng.randint(3,5)), c8
        for i in range(rng.randint(4,8)):
            cells.add((base_r+rng.randint(0,2), base_c+rng.randint(-2,2)))
    for r,c in cells:
        if 0<=r<H and 0<=c<W and g[r][c]==0: g[r][c]=2
    return g"}

